            lstCase[0].Sub_Status__c = responseWrap.current_status;
        }
    }
    if(String.isNotBlank(responseWrap.invisible_baserun_id)) {
        lstCase[0].External_Id__c = responseWrap.invisible_baserun_id;
    }
    if(String.isNotBlank(responseWrap.baserun_creation_date)) {
        lstCase[0].Invisible_Request_Received_Date__c = InvisibleInboundIntegration.getDateTime(responseWrap.baserun_creation_date);
    }
    if(String.isNotBlank(responseWrap.reason)) {
        lstCase[0].Reasons__c = responseWrap.reason;
    }
    if(String.isNotBlank(responseWrap.photo_coverage) && responseWrap.photo_coverage != 'None') {
        lstCase[0].Menu_Photo_Coverage__c = Decimal.valueOf(responseWrap.photo_coverage.trim());
    }
    if(String.isNotBlank(responseWrap.requestType)) {
        lstCase[0].Menu_Rework_Type__c = responseWrap.requestType;
    }
    if(String.isNotBlank(responseWrap.requestType)) {
        lstCase[0].Menu_Comment__c = lstCase[0].Menu_Comment__c +'\n'+responseWrap.comment;
    } else {
        lstCase[0].Menu_Comment__c = responseWrap.comment;
    }
    if(responseWrap.current_status == 'Complete' || responseWrap.current_status == 'Completed') {
        if(lstCase[0].Menu_Completion_Date__c == null) {
            lstCase[0].Menu_Completion_Date__c = DateTime.now();
            //Menu & Asset changes
            lstCase[0].Menu_Creation_Status__c = 'Complete';
            if(lstCase[0].Status == 'Menu & Assets') {
                if(lstCase[0].AssetId == null || lstCase[0].Asset_Delivery_Status__c == 'Complete') {
                    lstCase[0].Sub_Status__c = 'Complete';   
                } else if(lstCase[0].AssetId != null && lstCase[0].Asset.Order_id__c == null) {
                    lstCase[0].Sub_Status__c = 'Waiting OPS Actions';
                } else if(lstCase[0].Sub_Status__c == 'Confirm Invisible Received Case') {
                    lstCase[0].Sub_Status__c = 'In Progress';
                }
            }
            if(lstCase[0].Status == 'Menu Update') {
                lstCase[0].Sub_Status__c = 'Complete';
            }
        } else if(String.isNotBlank(responseWrap.requestType)){
            lstCase[0].Rework_Completion_Date__c = DateTime.now();
        }
    //Escalation changes
    } else if(responseWrap.current_status.containsIgnoreCase('Escalation')) {
        Id taskRecordTypeId = Schema.SObjectType.Task.getRecordTypeInfosByDeveloperName().get('Menu_Escalation').getRecordTypeId(); //CEBF-582
        Task t = new Task();
        t.Subject = responseWrap.reason;
        t.ActivityDate = Date.Today();
        t.Status = 'Open';
        t.Type = 'Menu Escalation';
        t.Priority = 'High';
        t.Escalation_Reasons__c = responseWrap.reason;
        if(lstCase[0].Opportunity__c != null) {
            t.OwnerId = lstCase[0].Opportunity__r.OwnerId;
            t.WhatId = lstCase[0].Opportunity__c;
        } else {
            t.OwnerId = lstCase[0].Account.OwnerId;
            t.WhatId = lstCase[0].AccountId;
        }
        t.Created__c = DateTime.now();
        t.Description = responseWrap.comment;
        t.ReminderDateTime = DateTime.now();
        t.IsReminderSet = true;
        t.RecordTypeId = taskRecordTypeId; //CEBF-582
        insert t;
        List<Task> lstTasks = [SELECT Id FROM Task WHERE WhatId=:lstCase[0].Opportunity__c AND Type = 'Menu Escalation'];
        if(lstTasks?.size() > 1) {
            try {
                ConnectApi.FeedItemInput feedItemInput = new ConnectApi.FeedItemInput();
                ConnectApi.MentionSegmentInput mentionSegmentInput = new ConnectApi.MentionSegmentInput();
                ConnectApi.MessageBodyInput messageBodyInput = new ConnectApi.MessageBodyInput();
                ConnectApi.TextSegmentInput textSegmentInput = new ConnectApi.TextSegmentInput();

                messageBodyInput.messageSegments = new List<ConnectApi.MessageSegmentInput>();

                mentionSegmentInput.id = lstCase[0].OwnerId;
                messageBodyInput.messageSegments.add(mentionSegmentInput);

                String message = ' Invisible escalated again, Could you take a look? ';
                message += '\n Reason : '+responseWrap.reason;
                message +='\n Number of escalations : '+lstTasks.size();

                String taskLink = URL.getOrgDomainUrl().toExternalForm()+'/'+t.id;
                String caseLink = URL.getOrgDomainUrl().toExternalForm()+'/'+lstCase[0].id;
                String accountLink = URL.getOrgDomainUrl().toExternalForm()+'/'+lstCase[0].AccountId;

                message +='\n Task Link : '+taskLink;
                message +='\n Case Link : '+caseLink;
                message +='\n Account Link : '+accountLink;

                textSegmentInput.text = message;
                messageBodyInput.messageSegments.add(textSegmentInput);

                feedItemInput.body = messageBodyInput;
                feedItemInput.feedElementType = ConnectApi.FeedElementType.FeedItem;
                feedItemInput.subjectId = lstCase[0].Id;

                ConnectApi.FeedElement feedElement = ConnectApi.ChatterFeeds.postFeedElement(Network.getNetworkId(), feedItemInput);
            } catch(Exception e) {}
        }
    }
    CaseTriggerHandler.skipEscalationValidation = true;
    update lstCase[0];
}{noformat}

